use vstd::prelude::*;

verus! {
    /// In-place reversal of a `Vec<u64>`.  On return,
    /// for every index `k` in `[0, len)`, the new `v@[k]`
    /// equals the old `v@[len−1−k]`.  No allocation is performed.
    fn reverse(v: &mut Vec<u64>)
        ensures
            // length is unchanged
            v@.len() == old(v@).len(),
            // for every position k, the element is reversed
            forall |k: nat|
                k < v@.len() ==>
                    v@.index(k) == old(v@).index(old(v@).len() - 1 - k)
    {
        // capture the original contents
        let old_v: Seq<u64> = v@;
        let n: nat = old_v.len();

        // if fewer than 2 elements, nothing to do
        if n >= 2 {
            let mut i: nat = 0;
            let mut j: nat = n - 1;
            // swap v[i] and v[j] while i<j
            while i < j
                invariant
                    // bounds on i and j
                    i <= j + 1,
                    j < n,
                    // length stays n
                    v@.len() == n,
                    // the prefix [0..i) is already reversed
                    forall |k: nat|
                        k < i ==>
                            v@.index(k) == old_v.index(n - 1 - k),
                    // the suffix (j..n) is already reversed
                    forall |k: nat|
                        j < k && k < n ==>
                            v@.index(k) == old_v.index(n - 1 - k),
                    // the “middle” between i and j is unchanged
                    forall |k: nat|
                        i <= k && k <= j ==>
                            v@.index(k) == old_v.index(k),
                decreases j - i
            {
                // perform one swap and advance the pointers
                v.swap(i, j);
                i = i + 1;
                j = j - 1;
            }
        }
    }
}

fn main() {
    // example usage; not part of the proof
    let mut v = Vec::from_slice(&[1u64, 2, 3, 4]);
    reverse(&mut v);
    assert!(v == vec![4,3,2,1]);
}